CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY, handle text NOT NULL UNIQUE CHECK(handle ~ '^[a-z0-9_]{3,24}$'), password_hash text NOT NULL, admin boolean NOT NULL DEFAULT false, banned boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS characters(user_id text PRIMARY KEY REFERENCES users(id), name text NOT NULL, venue text NOT NULL, state jsonb NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS wallets(id text PRIMARY KEY,user_id text REFERENCES users(id),kind text NOT NULL,balance bigint NOT NULL DEFAULT 0, CHECK(user_id IS NULL OR balance>=0),UNIQUE(user_id,kind));
CREATE TABLE IF NOT EXISTS transactions(id text PRIMARY KEY,actor text REFERENCES users(id),kind text NOT NULL,note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS ledger(id bigserial PRIMARY KEY,transaction_id text NOT NULL REFERENCES transactions(id),wallet_id text NOT NULL REFERENCES wallets(id),amount bigint NOT NULL CHECK(amount<>0));
CREATE OR REPLACE FUNCTION balanced_transaction() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF EXISTS(SELECT 1 FROM ledger WHERE transaction_id=NEW.transaction_id GROUP BY transaction_id HAVING sum(amount)<>0) THEN RAISE EXCEPTION 'unbalanced ledger'; END IF; RETURN NULL; END $$;
DROP TRIGGER IF EXISTS ledger_balanced ON ledger;
CREATE CONSTRAINT TRIGGER ledger_balanced AFTER INSERT OR UPDATE ON ledger DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION balanced_transaction();
CREATE TABLE IF NOT EXISTS requests(user_id text NOT NULL REFERENCES users(id),request_key text NOT NULL,body_hash text NOT NULL,response jsonb NOT NULL,PRIMARY KEY(user_id,request_key));
CREATE TABLE IF NOT EXISTS actions(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),kind text NOT NULL,target text NOT NULL,status text NOT NULL CHECK(status IN ('running','completed','cancelled','failed')),started_at timestamptz NOT NULL,due_at timestamptz NOT NULL,result jsonb NOT NULL DEFAULT '{}');
CREATE UNIQUE INDEX IF NOT EXISTS one_running_action ON actions(user_id) WHERE status='running';
CREATE INDEX IF NOT EXISTS action_due ON actions(due_at) WHERE status='running';
CREATE TABLE IF NOT EXISTS inventory(user_id text NOT NULL REFERENCES users(id),item text NOT NULL,quantity integer NOT NULL CHECK(quantity>=0),PRIMARY KEY(user_id,item));
CREATE TABLE IF NOT EXISTS qualifications(user_id text NOT NULL REFERENCES users(id),qualification text NOT NULL,created_at timestamptz NOT NULL,PRIMARY KEY(user_id,qualification));
CREATE TABLE IF NOT EXISTS messages(id text PRIMARY KEY,sender text NOT NULL REFERENCES users(id),recipient text REFERENCES users(id),venue text,body text NOT NULL CHECK(length(body) BETWEEN 1 AND 500),created_at timestamptz NOT NULL,CHECK((recipient IS NULL)<>(venue IS NULL)));
CREATE INDEX IF NOT EXISTS message_room ON messages(venue,created_at);
CREATE INDEX IF NOT EXISTS message_recipient ON messages(recipient,created_at);
CREATE TABLE IF NOT EXISTS blocks(owner text NOT NULL REFERENCES users(id),target text NOT NULL REFERENCES users(id),PRIMARY KEY(owner,target));
CREATE TABLE IF NOT EXISTS presence(user_id text PRIMARY KEY REFERENCES users(id),seen_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS encounters(id text PRIMARY KEY,attacker text NOT NULL REFERENCES users(id),victim text NOT NULL REFERENCES users(id),venue text NOT NULL,status text NOT NULL,defense text NOT NULL DEFAULT 'protect',amount bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL,due_at timestamptz NOT NULL,resolved_at timestamptz);
CREATE INDEX IF NOT EXISTS encounter_pair ON encounters(attacker,victim,created_at);
CREATE TABLE IF NOT EXISTS cases(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),encounter text REFERENCES encounters(id),status text NOT NULL,evidence jsonb NOT NULL,history jsonb NOT NULL,appealed boolean NOT NULL DEFAULT false,service_done boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS reports(id text PRIMARY KEY,reporter text NOT NULL REFERENCES users(id),target text NOT NULL REFERENCES users(id),reason text NOT NULL,status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id bigserial PRIMARY KEY,actor text NOT NULL REFERENCES users(id),event text NOT NULL,data jsonb NOT NULL,created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS outbox(id bigserial PRIMARY KEY,user_id text REFERENCES users(id),kind text NOT NULL,created_at timestamptz NOT NULL,delivered_at timestamptz);
CREATE TABLE IF NOT EXISTS settings(key text PRIMARY KEY,value jsonb NOT NULL);
INSERT INTO wallets(id,kind) VALUES('system','system') ON CONFLICT DO NOTHING;
